/*
 * 8x8 bitmap glyphs for the boot menu: space, 0-9, A-Z, ':', '-', '+', '.', '>'.
 *
 * Glyph data taken from the Linux kernel console font lib/fonts/font_8x8.c
 * (GPL-2.0, "Font file generated by cpi2fnt"). Bit 7 = leftmost pixel.
 * This file is GPL-2.0-only, so the titan2-boot binary as a whole is
 * distributed under GPL-2.0-only.
 */
