static inline const unsigned char *font8x8_get(char c)
{
	unsigned i;
	if (c >= 'a' && c <= 'z')
		c = c - 'a' + 'A';
	for (i = 0; i < sizeof(font8x8_tab) / sizeof(font8x8_tab[0]); i++)
		if (font8x8_tab[i].c == c)
			return font8x8_tab[i].rows;
	return font8x8_blank;
}

